                  <Trophy className="w-4 h-4 inline mr-1.5" />{translate('knockoutTab')}
                </button>
              </div>
            </div>
          )}

          {/* Round Robin: show RoundRobinView */}
          {(isRoundRobin && !isGroupStageKnockout) || (isGroupStageKnockout && gsActiveTab === 'group') ? (
            <div className="space-y-4" onClickCapture={handleRoundRobinClickCapture}>
              {bracket.stages
                .filter(s => s.type === 'ROUND_ROBIN')
                .map(stage => (
                  <div key={stage.id}>
                    <div className="space-y-6">
                      {(stage.groups ?? []).map((group, groupIndex) => {
                        const formattedGroupName = group.name || translate('groupName', { name: String.fromCharCode(65 + groupIndex) });
                        return (
                          <div key={group.id} className="space-y-3">
                            <PagedRoundRobinView
                              matches={group.matches ?? []}
                              groupName={formattedGroupName}
                              tiebreakerMode={tiebreakerMode}
                              onScheduleMatch={handleOpenScheduling}
                              selectedMatchId={selectedMatchId}
                              onSelectMatch={onSelectMatch}
                              onDoubleClickMatch={onDoubleClickMatch}
                              tournamentId={tournament.id}
                              stageId={stage.id}
                              roundConfig={stage.roundConfig}
                              groupId={group.id}
                              groupDragHandlers={groupDragHandlers}
                            />
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))}
              <BracketScoreEntryDialog
                match={roundRobinScoreChooserMatch}
                open={Boolean(roundRobinScoreChooserMatch)}
                isCheckingAccess={isRoundRobinScoreAccessLoading}
                tournamentSportRules={tournament.sportRules}
                onClose={closeRoundRobinScoreDialog}
                onSaved={() => { void refetchDivisionData?.(); }}
              />
              {bracket.stages.filter(s => s.type === 'ROUND_ROBIN').length === 0 && (
                <div className="text-center py-8 text-slate-400 italic text-sm">
                  {translate('noGroupStageData')}
                </div>
              )}
            </div>
          ) : (
            <DndContext
              sensors={sensors}
              onDragStart={handleBracketDragStart}
              onDragEnd={handleBracketDragEnd}
              onDragCancel={() => setActiveDragSource(null)}
            >
              <PublicBracketTab
                organizerActions={bracketActions}
                viewModeOverride={isFullscreen ? 'full' : 'paged'}
                tournament={tournament}
                divisionId={selectedDivisionId || undefined}
                onScheduleMatch={handleOpenScheduling}
                tiebreakerMode={tiebreakerMode}
                selectedMatchId={selectedMatchId}
                onSelectMatch={onSelectMatch}
                onDoubleClickMatch={onDoubleClickMatch}
                canScoreMatch={canScoreMatch}
                knockoutOnly
                dragHandlers={bracketDragHandlers}
                bracketSnapshot={bracket}
                hideHonors
                showGroupRankPlaceholders
              />
              <DragOverlay dropAnimation={null}>
                {activeDragSource ? (
                  <div
                    style={
                      activeDragBox
                        ? {
                            width: activeDragBox.width,
                            height: activeDragBox.height,
                            // dnd-kit parks the grabbed point under the cursor, so
                            // the card is pulled back by half its own size minus
                            // where the grab sat. The card now rides the cursor
                            // by its centre instead of by a corner.
                            transform: `translate(${activeDragBox.grabX - activeDragBox.width / 2}px, ${
                              activeDragBox.grabY - activeDragBox.height / 2
                            }px)`,
                          }
                        : { width: 250 }
                    }
                    className="pointer-events-none overflow-hidden rounded-lg border border-blue-400 bg-white px-3 py-2 shadow-lg ring-2 ring-blue-200 opacity-90"
                  >
                    <span className="block truncate text-xs font-bold text-slate-800">
                      {activeDragSource.participant.teamName}
                    </span>
                  </div>
                ) : null}
              </DragOverlay>
            </DndContext>
          )}
        </div>
      )}

      {/* Pool assignment popup for round robin and group-stage formats */}
      {isPoolArrangementModalOpen && usesPoolAssignment && (
        <BracketSetupModal
          open={isPoolArrangementModalOpen}
          onOpenChange={setIsPoolArrangementModalOpen}
          tournamentFormat={tournamentFormat}
          bracketType={bracketType}
          selectedDivision={divisions?.find((d) => d.id === selectedDivisionId) ?? null}
          participants={participants}
          numGroups={numGroups}
          setNumGroups={setNumGroups}
          teamsPerGroup={teamsPerGroup}
          setTeamsPerGroup={setTeamsPerGroup}
          teamsAdvancing={teamsAdvancing}
          bracket={bracket}
          isSubmitting={isGeneratingBracket || isSavingGroupAssignments}
          onAssignmentsChange={(assignments) => handleSaveGroupAssignments(assignments)}
          onConfirm={(assignments) => handleSaveGroupAssignments(assignments, true)}
        />
      )}

      {/* Regenerating rebuilds every match and clears the results already
          entered, so it only runs after this confirmation. */}
      <ConfirmModal
        open={isConfirmResetOpen}
        onOpenChange={setIsConfirmResetOpen}
        title={translate('regenerateBracketConfirmTitle')}
        confirmLabel={translate('regenerateBracket')}
        variant="danger"
        isLoading={isGeneratingBracket}
        onConfirm={() => {
          setIsConfirmResetOpen(false);
          void handleGenerateBracket();
        }}
      />
    </div>
  );
}

