      sets.some((set) => set.scoreOverride?.reason),
    );
  }).length;
  const penaltyCount = matches.reduce(
    (total, match) => total + (match.scoreDetails?.penalties?.length ?? 0),
    0,
  );
  const isDraft = tournamentStatus === 'DRAFT';

  return (
    <section className="space-y-6">

      {isDraft ? (
        <div className="flex items-start gap-3 rounded-lg border border-border bg-accent p-4 text-sm text-accent-foreground">
          <FlaskConical className="mt-0.5 h-5 w-5 flex-shrink-0 text-accent-foreground" />
          <div>
            <p className="font-bold">{translate('draftModeTitle')}</p>
            <p className="mt-1 font-medium text-content-secondary">{translate('draftModeDescription', { count: mockParticipantCount })}</p>
          </div>
        </div>
      ) : mockParticipantCount > 0 ? (
        <div className="flex items-start gap-3 rounded-lg border border-border bg-rose-50 p-4 text-sm font-semibold text-rose-900">
          <ShieldAlert className="mt-0.5 h-5 w-5 flex-shrink-0" />
          {translate('mockOutsideDraft', { count: mockParticipantCount })}
        </div>
      ) : null}

      {error ? (
        <div className="flex items-start gap-3 rounded-lg border border-border bg-surface-subtle p-4 text-sm font-semibold text-content-secondary">
          <AlertTriangle className="mt-0.5 h-5 w-5 flex-shrink-0" />
          <span>{error}</span>
        </div>
      ) : null}

      <section className="grid grid-cols-2 gap-x-6 gap-y-4 rounded-lg border border-border bg-card px-5 py-4 sm:grid-cols-4">
        <div className="min-w-0">
          <p className="text-xs font-bold uppercase tracking-[0.12em] text-accent-foreground">{translate('readyToCall')}</p>
          <p className="mt-1 text-xl font-bold tabular-nums text-content-primary">{readyToCall}</p>
        </div>
        <div className="min-w-0">
          <p className="text-xs font-bold uppercase tracking-[0.12em] text-amber-700">{translate('missingCoordination')}</p>
          <p className="mt-1 text-xl font-bold tabular-nums text-amber-800">{pendingAssignments}</p>
        </div>
        <div className="min-w-0">
          <p className="text-xs font-bold uppercase tracking-[0.12em] text-rose-700">{translate('overdueStart')}</p>
          <p className="mt-1 text-xl font-bold tabular-nums text-rose-800">{overdueStarts}</p>
        </div>
        <div className="min-w-0">
          <p className="text-xs font-bold uppercase tracking-[0.12em] text-amber-700">{translate('exceptionsDiscipline')}</p>
          <p className="mt-1 text-xl font-bold tabular-nums text-amber-800">{exceptionalMatchCount + penaltyCount}</p>
        </div>
      </section>

      <div className="sticky top-[calc(var(--app-header-height)+1rem)] z-20 rounded-lg border border-border bg-card/95 p-2 shadow-sm backdrop-blur">
        <div className="grid grid-cols-3 gap-2">
          {([
            { id: 'MATCHES', label: translate('matchesTab'), count: matches.length, icon: ListChecks },
            { id: 'PARTICIPANTS', label: translate('participantsTab'), count: participants.length, icon: Users },
            { id: 'ACTIVITY', label: translate('activityTab'), count: activityLog.length, icon: Activity },
          ] as const).map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setActiveTab(tab.id)}
                className={cn(
                  'flex min-w-0 items-center justify-center gap-2 rounded-lg px-3 py-3 text-xs font-bold transition-colors sm:text-sm',
                  isActive
                    ? 'bg-action-primary-hover text-white shadow-sm'
                    : 'text-muted hover:bg-surface-hover hover:text-content-primary',
                )}
              >
                <Icon className="h-4 w-4 flex-shrink-0" aria-hidden="true" />
                <span className="truncate">{tab.label}</span>
                <span className={isActive ? 'text-action-foreground' : 'text-content-muted'}>{tab.count}</span>
              </button>
            );
          })}
        </div>
      </div>

      {activeTab === 'MATCHES' ? (
        <OpsMatches
          matches={matches}
          isOperationalDataLoading={isOperationalDataLoading}
          error={error}
          referees={referees}
          activeMatchActionId={activeMatchActionId}
          focusedMatchId={focusedMatchId}
          onFocusMatch={onFocusMatch}
          tournamentSportRules={tournamentSportRules}
          matchInsights={matchInsights}
          onUpdateMatchSchedule={onUpdateMatchSchedule}
          onUpdateMatchScore={onUpdateMatchScore}
          onApplyMatchOperation={onApplyMatchOperation}
        />
      ) : null}

      {activeTab === 'PARTICIPANTS' ? (
        <OpsParticipants
          participants={participants}
          activeParticipantActionId={activeParticipantActionId}
          onKickParticipant={onKickParticipant}
        />
      ) : null}

      {activeTab === 'ACTIVITY' ? <OpsActivity activityLog={activityLog} /> : null}
    </section>
  );
}

content.text:
'use client';

import { useCallback, useState, type ReactNode } from 'react';
import { CalendarDays, Camera, Trophy, Users } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { Button } from '@/components/ui/Button';
import {
  Modal,
  ModalContent,
  ModalDescription,
  ModalHeader,
  ModalTitle,
} from '@/components/ui/Modal';
import { ManageFullscreenProvider } from '@/app/(public)/tournaments/[id]/components/bracket/manageFullscreen';

/**
 * Operation tabs hosted by the wide management overlay.
 * The introduction, settings and sponsor management stay in the page column,
 * so a `?tab=sponsors` deep link can never reopen this shell.
 */
export type ManageWideSection = 'registration' | 'bracket' | 'court_schedule' | 'livestream';

const MANAGE_WIDE_SECTIONS = [
  { id: 'registration', icon: Users },
  { id: 'bracket', icon: Trophy },
  { id: 'court_schedule', icon: CalendarDays },
  { id: 'livestream', icon: Camera },
] as const satisfies readonly { id: ManageWideSection; icon: LucideIcon }[];

export const isManageWideSection = (section: string): section is ManageWideSection =>
  (MANAGE_WIDE_SECTIONS as readonly { id: string }[]).some(({ id }) => id === section);

interface ManageWideOverlayProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  section: ManageWideSection;
  onSectionChange: (section: ManageWideSection) => void;
  title: string;
  description: string;
  /** Compact division navigation; null gives tournament-scoped content the full pane. */
  divisionNavigation: ReactNode;
  /** Rendered in the right pane. The hosted tab unmounts with the overlay. */
  children: ReactNode;
}

/**
 * Host for the operation tabs. Division-scoped sections get a compact selector
 * beside their content; tournament-scoped Camera uses the full content pane.
 * The hosted section unmounts on close; registration drafts that must survive
 * navigation live in `useManageState`.
 */
export function ManageWideOverlay({
  open,
  onOpenChange,
  section,
  onSectionChange,
  title,
  description,
  divisionNavigation,
  children,
}: ManageWideOverlayProps) {
  const translate = useTranslations('OrganizerManage');
  // The magnify control inside the bracket expands this dialog itself, not the
  // bracket layout, so the whole operation surface goes full screen.
  const [isFullscreen, setIsFullscreen] = useState(false);
  const activeTabRef = useCallback(
    (element: HTMLButtonElement | null) => {
      if (!open || !element) return;
      element.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    },
    [open],
  );

  return (
    <Modal open={open} onOpenChange={onOpenChange}>
      {/* The close target is 44px for this dialog only; the shared Modal keeps
          its own default for every other screen. */}
      <ModalContent
        data-testid="manage-wide-overlay"
        // Full screen is a bracket-reading mode: the tabs and the division
        // sidebar are chrome the reader does not need, and the bracket draws its
        // own shrink control in the corner they leave free.
        closeButtonClassName={isFullscreen ? 'hidden' : 'z-10 h-[44px] w-[44px] rounded-lg'}
        // Fixed height, not max-height: with max-h the dialog resized to whatever
        // the selected tab held, so switching tabs made the whole modal jump.
        // The panes already scroll, so a constant height costs no content.
        onEscapeKeyDown={(event) => {
          // Esc leaves full screen first; a second Esc closes the dialog.
          if (!isFullscreen) return;
          event.preventDefault();
          setIsFullscreen(false);
        }}
        // Inline styles outrank every class, including the base modal's
        // fixed left-[50%] top-[50%], so full screen cannot depend on Tailwind
        // emitting inset-0 before those.
        style={
          isFullscreen
            ? { position: 'fixed', top: 0, left: 0, width: '100vw', height: '100dvh', maxWidth: 'none', maxHeight: 'none', transform: 'none' }
            : undefined
        }
        className={`flex flex-col overflow-hidden border border-border bg-card p-0 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 duration-200 motion-reduce:animate-none ${
          isFullscreen
            ? 'fixed left-0! top-0! bottom-0! right-0! z-50 max-h-none max-w-none translate-x-0! translate-y-0! rounded-none'
            : 'max-w-screen-2xl w-[90vw] h-[96vh] max-h-[96vh] rounded-2xl'
        }`}
      >
        {/* The active tab already names the section, so the header is not shown.
            It stays for screen readers: the dialog needs an accessible name. */}
        <ModalHeader className="sr-only">
          <ModalTitle>{title}</ModalTitle>
          <ModalDescription>{description}</ModalDescription>
        </ModalHeader>
        <div className="flex min-h-0 flex-1 flex-col">
          {/* Four operation tabs stay in one row; each icon sits above its label, with room reserved for the close target. */}
          {!isFullscreen && (
            <div
              data-testid="manage-wide-operation-tabs"
              className="grid shrink-0 grid-cols-4 gap-1.5 border-b border-border bg-surface-subtle py-2 pl-3 pr-20"
            >
              {MANAGE_WIDE_SECTIONS.map(({ id, icon: Icon }) => {
                const isActive = section === id;
                const label = translate(`wideSections.${id}.title`);

                return (
                  <button
                    key={id}
                    type="button"
                    data-testid={`manage-wide-tab-${id}`}
                    aria-current={isActive ? 'page' : undefined}
                    ref={isActive ? activeTabRef : undefined}
                    onClick={() => onSectionChange(id)}
                    // Labels wrap at narrow widths; active and keyboard-focus states stay explicit.
                  className={`flex min-h-[4.5rem] min-w-0 w-full flex-col items-center justify-center gap-1.5 rounded-lg border px-1 py-2 text-center text-xs font-semibold sm:px-2
                    transition-colors duration-150 motion-reduce:transition-none focus-visible:outline-none
                    focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ${
                      isActive
                        ? 'border-primary bg-primary-light/30 text-primary'
                        : 'border-border bg-card text-content-secondary hover:bg-surface-hover hover:text-content-primary'
                    }`}
                  >
                    <Icon className="h-4 w-4 shrink-0" aria-hidden="true" />
                    <span
                      data-testid={`manage-wide-tab-label-${id}`}
                      className="min-w-0 max-w-full whitespace-normal break-words text-center leading-snug"
                    >
                      {label}
                    </span>
                  </button>
                );
              })}
            </div>
          )}
          <div className={`grid min-h-0 flex-1 ${
            isFullscreen || divisionNavigation === null
              ? 'grid-cols-1 grid-rows-[minmax(0,1fr)]'
              : 'grid-cols-1 grid-rows-[auto_minmax(0,1fr)] lg:grid-cols-[20rem_minmax(0,1fr)] lg:grid-rows-1'
          }`}>
            {!isFullscreen && divisionNavigation !== null && (
              <nav
                aria-label={translate('wideSections.navigationLabel')}
                data-testid="manage-wide-division-selector"
                className="min-w-0 border-b border-border bg-surface-subtle p-3 lg:overflow-y-auto lg:border-b-0 lg:border-r"
              >
                {divisionNavigation}
              </nav>
            )}
            <div data-testid="manage-wide-content" className="min-h-0 overflow-y-auto bg-card p-3 sm:p-4 md:p-6">
              <div
                key={section}
                className="min-h-full animate-in fade-in slide-in-from-right-2 duration-200 motion-reduce:animate-none"
              >
                <ManageFullscreenProvider value={{ isFullscreen, toggleFullscreen: () => setIsFullscreen((v) => !v) }}>
                  {children}
                </ManageFullscreenProvider>
              </div>
            </div>
          </div>
        </div>
      </ModalContent>
    </Modal>
  );
}

interface ManageWideEmptyStateProps {
  section: Exclude<ManageWideSection, 'livestream'>;
  onAddDivision: () => void;
}

/**
 * A tournament with no competition format has nothing to render inside the wide
 * tabs, so the right pane would open blank. Offer the same "add division"
 * action the selector header uses instead of an empty panel.
 */
export function ManageWideEmptyState({ section, onAddDivision }: ManageWideEmptyStateProps) {
  const translate = useTranslations('OrganizerManage');

  return (
    <div
      data-testid="manage-wide-empty"
      className="flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-200 bg-white p-8 text-center"
    >
      <p className="text-sm font-bold text-slate-900">{translate(`wideSections.${section}.emptyTitle`)}</p>
      <p className="mt-1 max-w-md text-xs font-medium text-slate-500">
        {translate(`wideSections.${section}.emptyDescription`)}
      </p>
      <Button
        type="button"
        data-testid="manage-wide-add-division"
        onClick={onAddDivision}
        className="mt-4 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs"
      >
        {translate(`wideSections.${section}.addDivision`)}
      </Button>
    </div>
  );
}

