function TrayParticipant({
  participant,
  translate,
  enabled,
}: {
  participant: BracketParticipant;
  translate: TranslationFn;
  enabled: boolean;
}) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `bracket-tray:${participant.id}`,
    disabled: !enabled,
    data: {
      source: {
        type: 'tray',
        participant,
      } satisfies BracketDragSource,
    },
  });

  return (
    <button
      ref={setNodeRef}
      type="button"
      {...attributes}
      {...listeners}
      disabled={!enabled}
      className={`inline-block max-w-[12rem] touch-none shrink-0 truncate rounded-lg border bg-white px-2.5 py-1 text-left text-xs font-bold text-slate-800 shadow-sm transition ${
        isDragging ? 'opacity-40 ring-2 ring-blue-400' : 'hover:border-blue-300 hover:shadow'
      }`}
      aria-label={translate('bracketDragParticipant')}
    >
      {participant.teamName}
    </button>
  );
}

/**
 * The staging tray lives inside the round header row, so it is one line tall and
 * its chips scroll sideways. A full-width block there pushed the round
 * navigation off screen, which is why the earlier layout was reverted.
 */
function OrganizerBracketTray({
  dragHandlers,
  translate,
}: {
  dragHandlers: NonNullable<BracketTabProps['dragHandlers']>;
  translate: TranslationFn;
}) {
  const participants = dragHandlers.trayParticipants ?? [];
  const { isOver, setNodeRef } = useDroppable({
    id: 'bracket-tray',
    disabled: !dragHandlers.enabled,
    data: { target: { type: 'tray' } },
  });

  return (
    <section
      ref={setNodeRef}
      data-bracket-tray={participants.length ? 'filled' : 'empty'}
      aria-label={translate('bracketTrayTitle')}
      title={participants.length === 0 ? translate('bracketTrayEmpty') : undefined}
      className={`flex w-fit min-h-9 min-w-0 items-center gap-2 rounded-lg border border-dashed px-2.5 py-1 transition sm:max-w-[26rem] ${
        participants.length === 0 ? '' : 'sm:min-w-[14rem]'
      } ${
        isOver ? 'border-blue-400 bg-blue-50 ring-2 ring-blue-200' : 'border-slate-300 bg-slate-50/70'
      }`}
    >
      <div className="flex shrink-0 items-center gap-1.5 text-slate-600">
        <Archive className="h-3.5 w-3.5 text-slate-400" aria-hidden="true" />
        <span className="whitespace-nowrap text-[11px] font-bold">{translate('bracketTrayTitle')}</span>
      </div>
      {/* Inline the label alone is the affordance; the long sentence would eat
          half the round header, so it lives in the tooltip instead. */}
      {participants.length > 0 && (
        <div className="flex min-w-0 flex-1 gap-1.5 overflow-x-auto no-scrollbar py-0.5">
          {participants.map((participant) => (
            <TrayParticipant
              key={participant.id}
              participant={participant}
              translate={translate}
              enabled={Boolean(dragHandlers.enabled)}
            />
          ))}
        </div>
      )}
    </section>
  );
}

